-- --- assert ------------------------------------------------------------------
do $$
declare n int;
begin
  -- No Tamil field anywhere carries a Devanagari-Extended character. The range
  -- is spelled out rather than named because Postgres has no such class.
  select count(*) into n from public.pooja_steps
   where coalesce(mantra_tamil, '') ~ '[\uA8E0-\uA8FF]';
  if n <> 0 then raise exception '% Tamil mantra(s) still carry a Vedic-extended sign', n; end if;

  -- ...nor any roman field, and no candrabindu either.
  select count(*) into n from public.pooja_steps
   where coalesce(mantra_translit, '') ~ '[\uA8E0-\uA8FF]'
      or coalesce(mantra_translit, '') like '%m̐%';
  if n <> 0 then raise exception '% roman mantra(s) still carry the candrabindu', n; end if;

  -- And the Devanagari is UNTOUCHED: the sign belongs there. If this is zero,
  -- something helpfully stripped the source instead of the derived columns.
  select count(*) into n from public.pooja_steps
   where coalesce(mantra_sanskrit, '') like '%ꣳ%';
  if n <> 4 then raise exception 'expected 4 step(s) to keep the sign in Devanagari, found %', n; end if;

  -- The repaired rows say what the book says.
  --
  -- Scoped to those four rows by name. An unscoped count of Tamil containing
  -- கும் returns eight, because ku followed by m is an ordinary Tamil
  -- sequence that occurs in mantras having nothing to do with this sign. The
  -- first draft asserted the unscoped count and would have passed on four
  -- unrelated rows while these four stayed broken.
  select count(*) into n from public.pooja_steps
   where pooja_id = 'nitya_panchayatana'
     and step_title_en in ('Naivedyam', 'Avahanam — Vinayaka', 'Dhoopam & Deepam', 'Karpura Neerajanam')
     and mantra_tamil like '%கும்%';
  if n <> 4 then raise exception 'only % of the 4 repaired step(s) say கும்', n; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

commit;
